<?php

declare (strict_types=1);
namespace PHPStan\Parser;

use PhpParser\Lexer;
use PHPStan\DependencyInjection\AutowiredService;
use PHPStan\Php\PhpVersion;
use const PHP_VERSION_ID;
#[AutowiredService]
final class LexerFactory
{
    private PhpVersion $phpVersion;
    public function __construct(PhpVersion $phpVersion)
    {
        $this->phpVersion = $phpVersion;
    }
    public function create(): Lexer
    {
        if ($this->phpVersion->versionId === PHP_VERSION_ID) {
            return new Lexer();
        }
        return new Lexer\Emulative(\PhpParser\PhpVersion::fromString($this->phpVersion->getVersionString()));
    }
    public function createEmulative(): Lexer\Emulative
    {
        return new Lexer\Emulative();
    }
}

==== src/Php/PhpVersionFactoryFactory.php
<?php

declare (strict_types=1);
namespace PHPStan\Php;

use PHPStan\DependencyInjection\AutowiredParameter;
use PHPStan\DependencyInjection\AutowiredService;
use PHPStan\Internal\ComposerHelper;
use function count;
use function end;
use function is_array;
use function is_int;
use function is_string;
#[AutowiredService]
final class PhpVersionFactoryFactory
{
    /**
     * @var int|array{min: int, max: int}|null
     */
    private $phpVersion;
    /**
     * @var string[]
     */
    private array $composerAutoloaderProjectPaths;
    /**
     * @param int|array{min: int, max: int}|null $phpVersion
     * @param string[] $composerAutoloaderProjectPaths
     */
    public function __construct(
        #[AutowiredParameter]
        $phpVersion,
        #[AutowiredParameter]
        array $composerAutoloaderProjectPaths
    )
    {
        $this->phpVersion = $phpVersion;
        $this->composerAutoloaderProjectPaths = $composerAutoloaderProjectPaths;
    }
    public function create(): \PHPStan\Php\PhpVersionFactory
    {
        $composerPhpVersion = null;
        if (count($this->composerAutoloaderProjectPaths) > 0) {
            $composerJsonPath = end($this->composerAutoloaderProjectPaths);
            $composer = ComposerHelper::getComposerConfig($composerJsonPath);
            if ($composer !== null) {
                $platformVersion = $composer['config']['platform']['php'] ?? null;
                if (is_string($platformVersion)) {
                    $composerPhpVersion = $platformVersion;
                }
            }
        }
        $versionId = null;
        if (is_int($this->phpVersion)) {
            $versionId = $this->phpVersion;
        }
        if (is_array($this->phpVersion)) {
            $versionId = $this->phpVersion['min'];
        }
        return new \PHPStan\Php\PhpVersionFactory($versionId, $composerPhpVersion);
    }
}

==== src/Php/PhpVersionFactory.php
<?php

declare (strict_types=1);
namespace PHPStan\Php;

use PHPStan\DependencyInjection\AutowiredService;
use function explode;
use function max;
use function min;
use const PHP_VERSION_ID;
#[AutowiredService(\null, '@PHPStan\Php\PhpVersionFactoryFactory::create')]
final class PhpVersionFactory
{
    private ?int $versionId;
    private ?string $composerPhpVersion;
    public const MIN_PHP_VERSION = 70100;
    public const MAX_PHP_VERSION = 80599;
    public const MAX_PHP5_VERSION = 50699;
    public const MAX_PHP7_VERSION = 70499;
    public function __construct(?int $versionId, ?string $composerPhpVersion)
    {
        $this->versionId = $versionId;
        $this->composerPhpVersion = $composerPhpVersion;
    }
    public function create(): \PHPStan\Php\PhpVersion
    {
        $versionId = $this->versionId;
        if ($versionId !== null) {
            $source = \PHPStan\Php\PhpVersion::SOURCE_CONFIG;
        } elseif ($this->composerPhpVersion !== null) {
            $parts = explode('.', $this->composerPhpVersion);
            $tmp = (int) $parts[0] * 10000 + (int) ($parts[1] ?? 0) * 100 + (int) ($parts[2] ?? 0);
            $tmp = max($tmp, self::MIN_PHP_VERSION);
            $versionId = min($tmp, self::MAX_PHP_VERSION);
            $source = \PHPStan\Php\PhpVersion::SOURCE_COMPOSER_PLATFORM_PHP;
        } else {
            $versionId = PHP_VERSION_ID;
            $source = \PHPStan\Php\PhpVersion::SOURCE_RUNTIME;
        }
        return new \PHPStan\Php\PhpVersion($versionId, $source);
    }
}

