<?php
declare(strict_types=1);

require '/Users/ab/Projects/peq-php-version-range/vendor/autoload.php';

use App\Analyzer\PhpStanAnalyzer\PhpStanAnalyzer;
use App\Analyzer\PhpStanAnalyzer\WorkingDirectory;
use App\Analyzer\PhpStanAnalyzer\PhpStanAutoloader;
use App\Analyzer\PhpStanAnalyzer\Collector\DependencyCollector;
use App\Analyzer\PhpStanAnalyzer\Collector\InClassMethodCollector;
use App\Analyzer\Graph\Node;
use PHPStan\DependencyInjection\ContainerFactory as PhpStanContainerFactory;
use Symfony\Component\Yaml\Yaml;

function containerFor(array $files, array $collectors, ?int $phpVersion): \PHPStan\DependencyInjection\Container
{
    (new PhpStanAutoloader())->ensureRegistered();
    $parameters = ['customRulesetUsed' => true, 'level' => 0];
    if ($phpVersion !== null) {
        $parameters['phpVersion'] = $phpVersion;
    }
    $neon = Yaml::dump([
        'services' => array_map(
            static fn (string $c): array => ['class' => $c, 'tags' => ['phpstan.collector']],
            $collectors,
        ),
        'parameters' => $parameters,
        'includes' => [],
    ], 4);
    $dir = WorkingDirectory::shared();
    $conf = $dir->write('phpstan-'.md5($neon).'.neon', $neon);

    return (new PhpStanContainerFactory(getcwd()))->create($dir->path, [$conf], $files);
}

$legacy = <<<'SRC'
<?php
namespace Legacy;

class Helper
{
    const NAME = 'helper';

    public function join(array $parts)
    {
        return implode(',', $parts);
    }
}

class Service
{
    /** @var Helper */
    private $helper;

    public function __construct(Helper $helper)
    {
        $this->helper = $helper;
    }

    public function run(array $parts)
    {
        $joined = $this->helper->join($parts);
        return strtoupper($joined) . Helper::NAME;
    }
}
SRC;

$modern = <<<'SRC'
<?php
namespace Modern;

enum Suit: string { case Hearts = 'H'; }

class Service
{
    public function __construct(private readonly Suit $suit) {}

    public function run(): string
    {
        return match ($this->suit) { Suit::Hearts => 'red' };
    }
}
SRC;

$dir = sys_get_temp_dir().'/peqspike-src';
@mkdir($dir);
file_put_contents($dir.'/legacy.php', $legacy);
file_put_contents($dir.'/modern.php', $modern);

$analyzer = new PhpStanAnalyzer();

foreach ([['legacy', 70100], ['modern', 70100], ['legacy', 80300], ['modern', 80300]] as [$name, $version]) {
    $file = $dir.'/'.$name.'.php';
    echo "=== {$name} @ {$version} ===\n";
    try {
        $container = containerFor([$file], [DependencyCollector::class, InClassMethodCollector::class], $version);
        $report = $analyzer->collect($container, [$file]);
        $symbols = array_values(array_unique(array_map(
